-- Non-destructive organization transfers and commission accounting. Existing wallet/order ledgers untouched.
BEGIN;
CREATE TABLE IF NOT EXISTS km_org_transfers(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),agent_org_id UUID NOT NULL REFERENCES km_organizations(id),from_org_id UUID NOT NULL REFERENCES km_organizations(id),to_org_id UUID NOT NULL REFERENCES km_organizations(id),mode TEXT NOT NULL CHECK(mode IN ('WITH_MEMBERS','AGENT_ONLY')),requested_by UUID NOT NULL REFERENCES km_users(id),approved_by UUID REFERENCES km_users(id),reason TEXT NOT NULL,member_count INTEGER NOT NULL DEFAULT 0,settlement_cutoff TIMESTAMPTZ,requested_at TIMESTAMPTZ NOT NULL DEFAULT now(),completed_at TIMESTAMPTZ,status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','COMPLETED','REJECTED')),CHECK(from_org_id<>to_org_id));
CREATE UNIQUE INDEX IF NOT EXISTS km_org_transfer_one_pending ON km_org_transfers(agent_org_id) WHERE status='PENDING';
CREATE TABLE IF NOT EXISTS km_org_membership_history(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),agent_org_id UUID NOT NULL REFERENCES km_organizations(id),parent_org_id UUID NOT NULL REFERENCES km_organizations(id),valid_from TIMESTAMPTZ NOT NULL,valid_to TIMESTAMPTZ,changed_by UUID REFERENCES km_users(id),transfer_id UUID REFERENCES km_org_transfers(id));
CREATE UNIQUE INDEX IF NOT EXISTS km_org_membership_one_current ON km_org_membership_history(agent_org_id) WHERE valid_to IS NULL;
CREATE TABLE IF NOT EXISTS km_commission_policies(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),organization_id UUID NOT NULL REFERENCES km_organizations(id),method TEXT NOT NULL CHECK(method IN ('GROSS','PARENT_SHARE')),rate_bps INTEGER NOT NULL CHECK(rate_bps BETWEEN 0 AND 10000),effective_from TIMESTAMPTZ NOT NULL,created_by UUID NOT NULL REFERENCES km_users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE INDEX IF NOT EXISTS km_commission_policy_by_org ON km_commission_policies(organization_id,effective_from DESC);
CREATE TABLE IF NOT EXISTS km_commission_fee_events(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),source_type TEXT NOT NULL,source_id TEXT NOT NULL,eligible_fee_krw BIGINT NOT NULL CHECK(eligible_fee_krw>=0),charged_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(source_type,source_id));
CREATE TABLE IF NOT EXISTS km_commission_ledger(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),fee_event_id UUID NOT NULL REFERENCES km_commission_fee_events(id),beneficiary_org_id UUID NOT NULL REFERENCES km_organizations(id),policy_id UUID NOT NULL REFERENCES km_commission_policies(id),amount_krw BIGINT NOT NULL CHECK(amount_krw>=0),status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','CONFIRMED','ON_HOLD','PAID','CANCELLED')),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(fee_event_id,beneficiary_org_id));
CREATE TABLE IF NOT EXISTS km_commission_settlements(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),beneficiary_org_id UUID NOT NULL REFERENCES km_organizations(id),period_start TIMESTAMPTZ NOT NULL,period_end TIMESTAMPTZ NOT NULL,gross_krw BIGINT NOT NULL DEFAULT 0,adjustment_krw BIGINT NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'AGGREGATING' CHECK(status IN ('AGGREGATING','PENDING','CONFIRMED','PAYABLE','PAID','ON_HOLD','CANCELLED')),paid_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(period_start<period_end),UNIQUE(beneficiary_org_id,period_start,period_end));
INSERT INTO km_org_permissions(key,allowed_roles,delegable,risk_level) VALUES('WITHDRAW_HOLD_REQUEST',ARRAY['SUB_HQ','AGENT'],TRUE,'MEDIUM'),('COMMISSION_VIEW',ARRAY['SUB_HQ','AGENT'],TRUE,'LOW'),('COMMISSION_POLICY_EDIT',ARRAY['SUB_HQ'],FALSE,'HIGH'),('MEMBER_ACTIVITY_VIEW',ARRAY['SUB_HQ','AGENT'],TRUE,'LOW') ON CONFLICT(key) DO NOTHING;
INSERT INTO km_org_membership_history(agent_org_id,parent_org_id,valid_from)
 SELECT o.id,o.parent_id,o.created_at FROM km_organizations o WHERE o.type='AGENT' AND o.parent_id IS NOT NULL ON CONFLICT DO NOTHING;
COMMIT;
